// Private Set: callers ask isGooglePhotoBackfillPlace(), they never get a mutable list.
const ALLOW = new Set([...BACKFILL_BROWSE_PLACE_IDS, ...BACKFILL_CHRISTMAS_VENUE_PLACE_IDS]);
export const GOOGLE_PHOTO_BACKFILL_PLACE_COUNT = ALLOW.size;
/** True only for an exact place id on this list. */
export function isGooglePhotoBackfillPlace(placeId) {
  return typeof placeId === "string" && ALLOW.has(placeId);
}
